package br.com.admeclesial.domain.organizacao;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="vinculo_organizacao_eclesial",schema="adm_eclesial") public class VinculoOrganizacaoEclesial {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,updatable=false) private UUID uuid; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organizacao_pai_id",nullable=false) private OrganizacaoEclesial organizacaoPai; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organizacao_filha_id",nullable=false) private OrganizacaoEclesial organizacaoFilha; @Enumerated(EnumType.STRING) @Column(name="tipo_vinculo",nullable=false,length=20) private TipoVinculoOrganizacao tipoVinculo; @Column(name="data_inicio",nullable=false) private LocalDate dataInicio; @Column(name="data_fim") private LocalDate dataFim; @Column(nullable=false) private boolean ativo=true; @Column(columnDefinition="text") private String observacao;
 @PrePersist void prePersist(){if(uuid==null)uuid=UUID.randomUUID();}
 public Long getId(){return id;} public UUID getUuid(){return uuid;} public OrganizacaoEclesial getOrganizacaoPai(){return organizacaoPai;} public OrganizacaoEclesial getOrganizacaoFilha(){return organizacaoFilha;} public TipoVinculoOrganizacao getTipoVinculo(){return tipoVinculo;} public LocalDate getDataInicio(){return dataInicio;} public LocalDate getDataFim(){return dataFim;} public boolean isAtivo(){return ativo;} public String getObservacao(){return observacao;}
 public void setOrganizacaoPai(OrganizacaoEclesial v){organizacaoPai=v;} public void setOrganizacaoFilha(OrganizacaoEclesial v){organizacaoFilha=v;} public void setTipoVinculo(TipoVinculoOrganizacao v){tipoVinculo=v;} public void setDataInicio(LocalDate v){dataInicio=v;} public void setDataFim(LocalDate v){dataFim=v;} public void setAtivo(boolean v){ativo=v;} public void setObservacao(String v){observacao=v;}
}
